import com.couchbase.client.java.Cluster
import com.couchbase.client.java.CouchbaseCluster
import com.couchbase.client.java.bucket.Bucket
import com.couchbase.client.java.query.N1qlQuery
import com.couchbase.client.java.query.N1qlQueryResult
import com.couchbase.client.java.query.N1qlQueryRow

class VenueIdMigration {
    private val cluster: Cluster
    private val bucket: Bucket

    constructor() {
        cluster = CouchbaseCluster.create("localhost")
        bucket = cluster.openBucket("wisk-couchbase-bucket")
    }

    fun migrate() {
        // Execute the query to get the unique venue_id values
        val query = N1qlQuery.simple("SELECT DISTINCT venue_id FROM `wisk-couchbase-bucket`._default._default")
        val result: N1qlQueryResult = bucket.query(query)

        // Iterate over the results and run an update statement for each venue_id
        for (row: N1qlQueryRow in result) {
            val venueId = row.value().getLong("venue_id")
            val updateQuery = "UPDATE `wisk-couchbase-bucket`._default._default AS doc " +
                    "SET doc.id = CONCAT('item_variation_', TO_STRING(doc.venue_id), '_', TO_STRING(doc.data.id)), " +
                    "doc.data.item_distributor_id = doc.data.id " +
                    "WHERE venue_id = $venueId AND doc.data.item_distributor_id is missing"
            bucket.query(N1qlQuery.simple(updateQuery))
        }

        // Clean up resources
        bucket.close()
        cluster.disconnect()
    }

    fun close() {
        bucket.close()
        cluster.disconnect()
    }
}
